+# never connects to the DAP hub — no hub presence, no [hub] connect line;
+# messaging falls back to the file fabric). Issue #988 tracks the real fix
+# (fa_hub_client crashes on a malformed peer x25519 in a presence frame);
+# flip this back to true (or delete the line) once that ships.
+hub: false
diff --git a/flutter_app/tool/network_send_probe.dart b/flutter_app/tool/network_send_probe.dart
new file mode 100644
index 000000000..bea97f91a
--- /dev/null
+++ b/flutter_app/tool/network_send_probe.dart
@@ -0,0 +1,126 @@
+// One-off E2E probe (issue #955 / invite verification): joins the
+// production fa_network as a fresh member (the "invited agent" path),
+// encrypts a fanet1 envelope for the channel key from the wallet, and
+// relays it. Never committed with secrets — reads the Keychain wallet
+// at runtime like the app does.
+//
+// Run: dart run tool/network_send_probe.dart <channelId> <text>
