    test('401 refreshes the token once and retries', () async {
      var tokenCalls = 0;
      var refreshCalls = 0;
      final authorizations = <String>[];
      var responses = 0;
      final client = MockClient((request) async {
        authorizations.add(request.headers['authorization']!);
