/** The shared persistent-context launch options (start + restartBrowser). */
function launchOptions() {
  return {
    executablePath: chromeBinary()!,
    headless: true, // new headless loads MV3 extensions
    args: [
      '--no-sandbox',
      '--disable-dev-shm-usage',
