+  final ch = await http.get(Uri.parse('$base/api/channels/$channelId'),
+      headers: {'authorization': 'Bearer $token'});
+  final channelName = jsonDecode(ch.body)['name'] as String? ?? channelId;
+  stdout.writeln('[channel] $channelName');
