                'message': {'role': 'assistant', 'content': 'Hello!'},
              },
            ],
          }),
          200,
        );
      });

      final provider = CopilotProvider(
        token: () async => 'copilot-tok',
        baseUrl: base,
        defaultModel: 'gpt-4o',
        client: client,
