          const LlmMessage(role: 'user', content: 'q'),
        ]);
        await provider.chatMessages([
          const LlmMessage(role: 'user', content: 'q'),
          const LlmMessage(role: 'assistant', content: 'a'),
        ]);
        await provider.chatMessages([
