      expect(headers['editor-version'], 'vscode/1.109.3');
      expect(headers['editor-plugin-version'], 'copilot-chat/0.37.6');
      expect(headers['user-agent'], 'GitHubCopilotChat/0.37.6');
      expect(headers['openai-intent'], 'conversation-agent');
