                'message': {'content': 'ok'},
              },
            ],
          }),
          200,
        );
      });
      final provider = CopilotProvider(
        token: () async => 't',
        baseUrl: base,
        defaultModel: 'm',
        client: client,
      );

      await provider.chatMessages([
        LlmMessage(
          role: 'user',
          content: 'look',
          images: ['data:image/png;base64,AAAA'],
