diff --git a/packages/fa_llm/test/copilot_provider_test.dart b/packages/fa_llm/test/copilot_provider_test.dart
index 0bd345ae8..bf8e35e6b 100644
--- a/packages/fa_llm/test/copilot_provider_test.dart
+++ b/packages/fa_llm/test/copilot_provider_test.dart
@@ -273,6 +273,42 @@ void main() {
       expect(responses, 2);
     });

+    test(
+      'a successful 2xx response is returned as-is — no refresh, no '
+      're-send (REG: inverted retry predicate re-POSTed every request)',
+      () async {
+        var responses = 0;
+        var refreshCalls = 0;
+        final client = MockClient((request) async {
+          responses++;
+          return http.Response(
+            jsonEncode({
+              'choices': [
+                {
+                  'message': {'content': 'ok'},
+                },
+              ],
+            }),
+            200,
+          );
+        });
+        final provider = CopilotProvider(
+          token: () async => 't1',
+          refresh: () async {
+            refreshCalls++;
+            return 't2';
+          },
+          baseUrl: base,
+          defaultModel: 'm',
+          client: client,
+        );
+
+        expect(await provider.chat('hi'), 'ok');
+        expect(responses, 1);
+        expect(refreshCalls, 0);
+      },
+    );
+
     test('second 401 surfaces an error', () async {
       var refreshCalls = 0;
       final client = MockClient((_) async => http.Response('expired', 401));
diff --git a/scripts/build_browser_ext.sh b/scripts/build_browser_ext.sh
index dc9eae6fb..b50a56991 100755
--- a/scripts/build_browser_ext.sh
+++ b/scripts/build_browser_ext.sh
@@ -234,6 +234,8 @@ open(sys.argv[2], "w").write(json.dumps(m, indent=2) + "\n")
 elif command -v node >/dev/null 2>&1; then
   node -e 'const fs=require("fs"); const m=JSON.parse(fs.readFileSync(process.argv[1], "utf8").replace(/^\s*\/\/.*$/gm, "")); delete m.key; fs.writeFileSync(process.argv[2], JSON.stringify(m, null, 2) + "\n")' "$manifest" build/pack/manifest.json
 else
+  echo "WARNING: no python3/node — packaging the RAW source manifest;" \
+       "the strict guard below is expected to fail (CWS needs stripped JSON)" >&2
   cp "$manifest" build/pack/manifest.json
 fi

